function getJalaliYearDifference(startStr: string, endStr: string): number {
  const start = parseJalali(startStr);
  const end = parseJalali(endStr);
  if (!start || !end) return 0;
  
  let years = end.y - start.y;
  if (end.m < start.m || (end.m === start.m && end.d < start.d)) {
    years--;
  }
  return Math.max(0, years);
}

function getJalaliDateDifference(startStr: string, endStr: string) {
  const start = parseJalali(startStr);
  const end = parseJalali(endStr);
  if (!start || !end) return null;

  let years = end.y - start.y;
  let months = end.m - start.m;
  let days = end.d - start.d;

  if (days < 0) {
    let prevMonth = end.m - 1;
    if (prevMonth === 0) {
      prevMonth = 12;
    }
    
    let prevMonthDays = 30;
    if (prevMonth <= 6) {
      prevMonthDays = 31;
    } else if (prevMonth === 12) {
      prevMonthDays = 29;
    }
    
    days += prevMonthDays;
    months--;
  }

  if (months < 0) {
    months += 12;
    years--;
  }

  return {
    years: Math.max(0, years),
    months: Math.max(0, months),
    days: Math.max(0, days)
  };
}

function calculateJalaliContractMonths(startStr: string, endStr: string): number {
  const start = parseJalali(startStr);
  const end = parseJalali(endStr);
  if (!start || !end) return 0;

  const getDays = (y: number, m: number, d: number) => {
    let days = y * 365 + Math.floor((y + 38) * 31 / 128);
    for (let i = 1; i < m; i++) {
      if (i <= 6) days += 31;
      else if (i <= 11) days += 30;
      else days += 29;
    }
    days += d;
    return days;
  };

  const days1 = getDays(start.y, start.m, start.d);
  const days2 = getDays(end.y, end.m, end.d);
  const totalDays = days2 - days1 + 1;
  if (totalDays <= 0) return 0;

  const calculated = Math.round(totalDays / 30.43);
  return Math.max(1, calculated);
}

function formatJalaliDifference(diff: { years: number, months: number, days: number } | null): string {
  if (!diff) return 'نامشخص';
  const parts: string[] = [];
  if (diff.years > 0) {
    parts.push(`${diff.years} سال`);
  }
  if (diff.months > 0) {
    parts.push(`${diff.months} ماه`);
  }
  if (diff.days > 0) {
    parts.push(`${diff.days} روز`);
  }
  if (parts.length === 0) {
    return 'کمتر از یک روز';
  }
  return parts.join(' و ');
}

const shallowEqualRecord = (a: Record<string, number>, b: Record<string, number>): boolean => {
  if (a === b) return true;
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (let i = 0; i < keysA.length; i++) {
    const k = keysA[i];
    if (a[k] !== b[k]) return false;
  }
  return true;
};

const formatMinutesToHMHelper = (mins: number): string => {
  const isNegative = mins < 0;
  const absMins = Math.abs(Math.round(mins));
  const h = Math.floor(absMins / 60);
  const m = absMins % 60;
  return `${isNegative ? '-' : ''}${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const parseHMToMinutesHelper = (hm?: string): number => {
  if (!hm) return 0;
  const eng = toEnglishDigits(String(hm)).trim();
  const pts = eng.split(':');
  if (pts.length !== 2) return 0;
  return ((parseInt(pts[0], 10) || 0) * 60) + (parseInt(pts[1], 10) || 0);
};

const roundMinutesToHourHelper = (mins?: number): number => {
  const res = Math.round((mins || 0) / 60);
  return res === 0 ? 0 : res;
};

const parseHMToRoundedHourHelper = (hm?: string, fallbackHours?: number): number => {
  if (hm) {
    const eng = toEnglishDigits(String(hm)).trim();
    if (eng.includes(':')) {
      return roundMinutesToHourHelper(parseHMToMinutesHelper(eng));
    }
    const num = parseFloat(eng);
    if (!isNaN(num)) {
      const res = Math.round(num);
      return res === 0 ? 0 : res;
    }
  }
  const res = Math.round(fallbackHours || 0);
  return res === 0 ? 0 : res;
};

const computeProgressiveTaxHelper = (
  taxBase: number,
  monthlyExemption: number,
  yearBrackets: any[]
): number => {
  if (taxBase <= monthlyExemption) return 0;
  if (yearBrackets.length > 0) {
    let taxSum = 0;
    for (let i = 0; i < yearBrackets.length; i++) {
      const b = yearBrackets[i];
      const from = Number(b.fromAmount);
      const to = b.toAmount !== null && b.toAmount !== undefined && Number(b.toAmount) > 0 ? Number(b.toAmount) : Infinity;
      const rate = Number(b.taxRate) / 100;
      if (taxBase > from) {
        const portion = Math.min(taxBase, to) - from;
        if (portion > 0) taxSum += portion * rate;
      }
    }
    return Math.round(taxSum);
  }
  let taxSum = 0;
  const limit1 = monthlyExemption;
  const limit2 = Math.round(monthlyExemption * 1.375);
  const limit3 = Math.round(monthlyExemption * 2.25);
  const limit4 = Math.round(monthlyExemption * 3.3333);
  if (taxBase > limit1) {
    const b1 = Math.min(taxBase, limit2) - limit1;
    if (b1 > 0) taxSum += b1 * 0.10;
  }
  if (taxBase > limit2) {
    const b2 = Math.min(taxBase, limit3) - limit2;
    if (b2 > 0) taxSum += b2 * 0.15;
  }
  if (taxBase > limit3) {
    const b3 = Math.min(taxBase, limit4) - limit3;
    if (b3 > 0) taxSum += b3 * 0.20;
  }
  if (taxBase > limit4) {
    const b4 = taxBase - limit4;
    if (b4 > 0) taxSum += b4 * 0.30;
  }
  return Math.round(taxSum);
};

interface BufferedInputProps {
  value: number | string | undefined;
  onCommit: (val: number) => void;
  type?: 'number' | 'currency';
  min?: number;
  max?: number;
  step?: number | string;
  className?: string;
  placeholder?: string;
  title?: string;
  disabled?: boolean;
}

const BufferedInput: React.FC<BufferedInputProps> = React.memo(({
  value,
  onCommit,
  type = 'number',
  min,
  max,
  step = 1,
  className = '',
  placeholder = '۰',
  title = '',
  disabled = false
}) => {
  const formatDisplay = (v: number | string | undefined): string => {
    if (v === undefined || v === null || v === '') return '';
    if (type === 'currency') {
      const num = typeof v === 'string' ? parseInt(v.replace(/,/g, '').replace(/[^\d]/g, ''), 10) : Number(v);
      return isNaN(num) ? '' : formatWithCommas(num);
    }
    return String(v);
  };

  const [localValue, setLocalValue] = useState<string>(() => formatDisplay(value));
  const isEditingRef = useRef(false);

  useEffect(() => {
    if (!isEditingRef.current) {
      setLocalValue(formatDisplay(value));
    }
  }, [value, type]);

  const commitValue = (valStr: string) => {
    let parsed: number;
    if (type === 'currency') {
      const clean = toEnglishDigits(valStr).replace(/,/g, '').replace(/[^\d]/g, '');
      parsed = parseInt(clean, 10);
    } else {
      const clean = toEnglishDigits(valStr).replace(/[^\d.-]/g, '');
      parsed = parseFloat(clean);
    }
    const finalVal = isNaN(parsed) ? 0 : parsed;
    onCommit(finalVal);
  };

  useEffect(() => {
    if (!isEditingRef.current) return;
    const timer = setTimeout(() => {
      commitValue(localValue);
    }, 350);
    return () => clearTimeout(timer);
  }, [localValue]);

  const handleBlur = () => {
    isEditingRef.current = false;
    commitValue(localValue);
    setLocalValue(formatDisplay(value));
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    isEditingRef.current = true;
    const raw = e.target.value;
    if (type === 'currency') {
      const clean = toEnglishDigits(raw).replace(/,/g, '').replace(/[^\d]/g, '');
      if (!clean) {
        setLocalValue('');
      } else {
        const num = parseInt(clean, 10);
        setLocalValue(isNaN(num) ? '' : formatWithCommas(num));
      }
    } else {
      setLocalValue(raw);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      (e.target as HTMLInputElement).blur();
    }
  };

  return (
    <input
      type={type === 'currency' ? 'text' : 'number'}
      min={min}
      max={max}
      step={step}
      value={localValue}
      onChange={handleChange}
      onBlur={handleBlur}
      onKeyDown={handleKeyDown}
      onFocus={(e) => {
        isEditingRef.current = true;
        e.target.select();
      }}
      placeholder={placeholder}
      className={className}
      title={title}
      disabled={disabled}
    />
  );
});


