const getEligibleChildrenCount = (insuranceHistoryDays: number, list: PersonnelChild[] = []): number => {
  if (insuranceHistoryDays < 730) return 0;
  return (list || []).filter(ch => {
    if (ch.gender === 'پسر') {
      return ch.age < 18 || (ch.age >= 18 && ch.isStudent === true);
    } else if (ch.gender === 'دختر') {
      return true;
    }
    return false;
  }).length;
};

const normalizeRateDateYMD = (d?: string): string => {
  if (!d) return '';
  const clean = toEnglishDigits(String(d)).trim().replace(/[-.\s]+/g, '/');
  const m = clean.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);
  if (!m) return '';
  return `${m[1]}/${m[2].padStart(2, '0')}/${m[3].padStart(2, '0')}`;
};

export const findSalaryBaseRateByDate = (
  rates: SalaryBaseRate[],
  targetDateStr?: string,
  fallbackYearStr?: string
): SalaryBaseRate | undefined => {
  if (!rates || rates.length === 0) return undefined;
  const normTarget = normalizeRateDateYMD(targetDateStr);
  const yearStr = fallbackYearStr
    ? toEnglishDigits(String(fallbackYearStr)).trim()
    : (normTarget ? normTarget.slice(0, 4) : '');

  if (normTarget) {
    const datedMatches = rates.filter((r) => {
      const s = normalizeRateDateYMD(r.startDate);
      const e = normalizeRateDateYMD(r.endDate);
      if (!s && !e) return false;
      if (s && normTarget < s) return false;
      if (e && normTarget > e) return false;
      return true;
    });
    if (datedMatches.length > 0) {
      datedMatches.sort((a, b) => normalizeRateDateYMD(b.startDate).localeCompare(normalizeRateDateYMD(a.startDate)));
      return datedMatches[0];
    }
  }

  if (yearStr) {
    const yearMatches = rates.filter((r) => toEnglishDigits(String(r.year || '')).trim() === yearStr);
    if (yearMatches.length > 0) {
      const undated = yearMatches.find((r) => !normalizeRateDateYMD(r.startDate) && !normalizeRateDateYMD(r.endDate));
      if (undated && !normTarget) return undated;
      const sorted = [...yearMatches].sort((a, b) => normalizeRateDateYMD(b.startDate).localeCompare(normalizeRateDateYMD(a.startDate)));
      return sorted[0];
    }
  }

  return undefined;
};

export const findSeniorityRateRule = (
  rules: SeniorityRateRule[],
  seniorityYears: number,
  targetDateStr?: string,
  fallbackYearStr?: string,
  activePeriodId?: string
): SeniorityRateRule | undefined => {
  if (!rules || rules.length === 0) return undefined;
  const scoped = activePeriodId ? rules.filter(r => r.periodId === activePeriodId) : rules;
  const pool = scoped.length > 0 ? scoped : rules;
  const byYears = pool.filter(r => Number(r.seniorityYears) === Number(seniorityYears));
  if (byYears.length === 0) return undefined;

  const normTarget = normalizeRateDateYMD(targetDateStr);
  const yearStr = fallbackYearStr
    ? toEnglishDigits(String(fallbackYearStr)).trim()
    : (normTarget ? normTarget.slice(0, 4) : '');

  if (normTarget) {
    const datedMatches = byYears.filter((r) => {
      const s = normalizeRateDateYMD(r.startDate);
      const e = normalizeRateDateYMD(r.endDate);
      if (!s && !e) return false;
      if (s && normTarget < s) return false;
      if (e && normTarget > e) return false;
      return true;
    });
    if (datedMatches.length > 0) {
      datedMatches.sort((a, b) => normalizeRateDateYMD(b.startDate).localeCompare(normalizeRateDateYMD(a.startDate)));
      return datedMatches[0];
    }
  }

  if (yearStr) {
    const yearMatches = byYears.filter((r) => toEnglishDigits(String(r.fiscalYear || '')).trim() === yearStr);
    if (yearMatches.length > 0) {
      const undated = yearMatches.find((r) => !normalizeRateDateYMD(r.startDate) && !normalizeRateDateYMD(r.endDate));
      if (undated && !normTarget) return undated;
      const sorted = [...yearMatches].sort((a, b) => normalizeRateDateYMD(b.startDate).localeCompare(normalizeRateDateYMD(a.startDate)));
      return sorted[0];
    }
  }

  return undefined;
};

export const getSalaryBaseRateForYearMonth = (
  db: AppDatabase,
  year?: number | string,
  month?: number | string,
  activePeriodId?: string
): SalaryBaseRate | undefined => {
  const allRates = db.salaryBaseRates || [];
  const periodRates = activePeriodId ? allRates.filter((r: any) => r.periodId === activePeriodId) : allRates;
  const rates = periodRates.length > 0 ? periodRates : allRates;
  if (rates.length === 0) return undefined;

  const activePeriodObj = activePeriodId ? (db.periods || []).find(p => p.id === activePeriodId) : undefined;
  const targetYearStr = year
    ? toEnglishDigits(String(year)).trim()
    : (activePeriodId ? String(getFiscalYearFromPeriod(activePeriodObj, activePeriodId)) : '');
  const targetMonthStr = month ? String(month).padStart(2, '0') : '';

  if (targetYearStr && targetMonthStr) {
    const midMonthDate = `${targetYearStr}/${targetMonthStr}/15`;
    const matchedByDate = findSalaryBaseRateByDate(rates, midMonthDate, targetYearStr);
    if (matchedByDate) return matchedByDate;
  }

  if (targetYearStr) {
    if (activePeriodId) {
      const matchedByActivePeriod = findSalaryBaseRateByDate(
        rates.filter((r: any) => r.periodId === activePeriodId),
        undefined,
        targetYearStr
      );
      if (matchedByActivePeriod) return matchedByActivePeriod;
    }

    if (targetMonthStr) {
      const periodYM = `${targetYearStr}-${targetMonthStr}`;
      const matchedByYM = rates.find((r: any) => toEnglishDigits(String(r.year || '')).trim() === targetYearStr && r.periodId === periodYM);
      if (matchedByYM) return matchedByYM;
    }

    const matchedByYear = findSalaryBaseRateByDate(rates, undefined, targetYearStr);
    if (matchedByYear) return matchedByYear;
  }

  if (activePeriodId) {
    const matchedByActivePeriod = rates.find((r: any) => r.periodId === activePeriodId);
    if (matchedByActivePeriod) return matchedByActivePeriod;
  }

  const sorted = [...rates].sort((a: any, b: any) => {
    const yDiff = (Number(toEnglishDigits(String(b.year || ''))) || 0) - (Number(toEnglishDigits(String(a.year || ''))) || 0);
    if (yDiff !== 0) return yDiff;
    return normalizeRateDateYMD(b.startDate).localeCompare(normalizeRateDateYMD(a.startDate));
  });
  return sorted[0] || rates[0];
};

export const getMatchingSalaryBaseRate = getSalaryBaseRateForYearMonth;

const resolveOvertimeHolidayFridayRates = (
  dailyBase: number,
  activeRates: SalaryBaseRate | undefined,
  activeBaseDailyVal?: number
) => {
  const refActiveDaily = activeBaseDailyVal !== undefined
    ? activeBaseDailyVal
    : (activeRates && Number(activeRates.dailyBaseSalary) > 0 ? Number(activeRates.dailyBaseSalary) : 0);
  const useActiveRates = Boolean(activeRates) && (refActiveDaily === 0 || dailyBase === refActiveDaily);

  const defaultOt = Math.round((dailyBase * 1.4) / 7.33);
  const defaultFri = Math.round(((dailyBase || 0) * 0.40) / 7.33);

  let overtimeHourlyRateVal = defaultOt;
  if (useActiveRates && Number(activeRates?.overtimeHourlyRate) > 0) {
    const rawOt = Number(activeRates!.overtimeHourlyRate);
    overtimeHourlyRateVal = (refActiveDaily > 0 && rawOt > (refActiveDaily * 0.8))
      ? Math.round(rawOt / 7.33)
      : rawOt;
  }

  let fridayWorkHourlyRateVal = defaultFri;
  if (useActiveRates && Number(activeRates?.fridayWorkHourlyRate) > 0) {
    const rawFri = Number(activeRates!.fridayWorkHourlyRate);
    fridayWorkHourlyRateVal = (refActiveDaily > 0 && rawFri > (refActiveDaily * 0.15))
      ? Math.round(rawFri / 7.33)
      : rawFri;
  } else if (dailyBase > 0 && fridayWorkHourlyRateVal > (dailyBase * 0.15)) {
    fridayWorkHourlyRateVal = Math.round(fridayWorkHourlyRateVal / 7.33);
  }

  let holidayWorkHourlyRateVal = overtimeHourlyRateVal;
  if (useActiveRates && Number(activeRates?.holidayWorkHourlyRate) > 0) {
    const rawHol = Number(activeRates!.holidayWorkHourlyRate);
    holidayWorkHourlyRateVal = (refActiveDaily > 0 && rawHol > (refActiveDaily * 0.8))
      ? Math.round(rawHol / 7.33)
      : rawHol;
  }

  return {
    overtimeHourlyRateVal,
    fridayWorkHourlyRateVal,
    holidayWorkHourlyRateVal
  };
};

export const getSalaryBaseRateForContract = (
  c: any,
  emp: any,
  db: AppDatabase,
  activePeriodId: string,
  calcYear?: number | string
): SalaryBaseRate | undefined => {
  const allRates = db.salaryBaseRates || [];
  const periodRates = allRates.filter((r: any) => !activePeriodId || r.periodId === activePeriodId);
  const rates = periodRates.length > 0 ? periodRates : allRates;
  if (rates.length === 0) return undefined;

  // 1. Explicit manual/saved SalaryBaseRate ID on contract takes highest priority
  const explicitRateId = c?.salaryBaseRateId || c?.contract?.salaryBaseRateId;
  if (explicitRateId) {
    const byId = periodRates.find((r: any) => r.id === explicitRateId) || allRates.find((r: any) => r.id === explicitRateId);
    if (byId) return byId;
  }

  const activePeriodObj = (db.periods || []).find(p => p.id === activePeriodId);
  const activeYear = activePeriodId ? String(getFiscalYearFromPeriod(activePeriodObj, activePeriodId)) : '';
  const contractPeriodObj = c?.periodId ? (db.periods || []).find(p => p.id === c.periodId) : undefined;
  const periodYear = c?.periodId ? String(getFiscalYearFromPeriod(contractPeriodObj, c.periodId)) : '';
  const startDateStr = c?.contractStartDate || emp?.contractStartDate || emp?.entryDate || '';
  const endDateStr = c?.contractEndDate || emp?.contractEndDate || '';
  const startYear = getJalaliYear(startDateStr);
  const endYear = getJalaliYear(endDateStr);

  // 2. Automatic date-range match using contract start date
  const normStart = normalizeRateDateYMD(startDateStr);
  if (normStart && (!calcYear || toEnglishDigits(String(calcYear)).trim() === startYear)) {
    const byDate = findSalaryBaseRateByDate(rates, normStart, startYear);
    if (byDate) return byDate;
  }

  // 3. Fallback to year matching
  const targetYear = calcYear
    ? String(calcYear).trim()
    : (startYear || activeYear || periodYear || endYear);

  if (targetYear) {
    const matched = getSalaryBaseRateForYearMonth(db, targetYear, undefined, activePeriodId);
    if (matched) return matched;
  }

  return rates[0];
};

export const getContractPeriodId = (
  c: any,
  emp: any,
  db: AppDatabase,
  fallbackPeriodId: string
): string => {
  const periods = db.periods || [];
  const conStart = c?.contractStartDate || emp?.contractStartDate || emp?.entryDate || '';

  if (conStart) {
    const cleanStart = toEnglishDigits(conStart).replace(/-/g, '/').trim();

    // 1. Direct date range match in db.periods (startDate <= contractStartDate <= endDate)
    const matchedRange = periods.find(p => {
      if (p.startDate && p.endDate) {
        const pStart = toEnglishDigits(p.startDate).replace(/-/g, '/').trim();
        const pEnd = toEnglishDigits(p.endDate).replace(/-/g, '/').trim();
        return cleanStart >= pStart && cleanStart <= pEnd;
      }
      return false;
    });
    if (matchedRange) return matchedRange.id;

    // 2. Year-month match (e.g., "1404/02/10" -> "1404-02")
    const parts = cleanStart.split('/');
    if (parts.length >= 2) {
      const year = parts[0];
      const month = parts[1].padStart(2, '0');
      const ymId = `${year}-${month}`;
      const matchedYm = periods.find(p => p.id === ymId);
      if (matchedYm) return matchedYm.id;

      // Match any period starting with this year that has insured/taxable items configured
      const periodInYearWithItems = periods.find(p =>
        p.id.startsWith(year) && (db.insuredSalaryItems || []).some((item: any) => item.periodId === p.id)
      );
      if (periodInYearWithItems) return periodInYearWithItems.id;

      // Any period in this year
      const anyInYear = periods.find(p => p.id.startsWith(year));
      if (anyInYear) return anyInYear.id;
    }
  }

  // 3. Fallback: match by contract periodId if it exists in db.periods
  if (c?.periodId && periods.some(p => p.id === c.periodId)) {
    return c.periodId;
  }
  if (emp?.periodId && periods.some(p => p.id === emp.periodId)) {
    return emp.periodId;
  }

  return fallbackPeriodId;
};

export const getInsuredSalaryItemsForContract = (
  c: any,
  emp: any,
  db: AppDatabase,
  fallbackPeriodId: string
): { periodId: string; items: any[] } => {
  const allInsured = (db.insuredSalaryItems || []).filter((item: any) => !fallbackPeriodId || item.periodId === fallbackPeriodId);
  if (allInsured.length === 0) {
    return { periodId: fallbackPeriodId, items: [] };
  }

  const targetPeriodId = fallbackPeriodId || getContractPeriodId(c, emp, db, fallbackPeriodId);
  const conStartRaw = c?.contractStartDate || emp?.contractStartDate || emp?.entryDate || c?.date || c?.monthDate || '';
  const conEndRaw = c?.contractEndDate || emp?.contractEndDate || '';
  const monthDateRaw = c?.monthDate || c?.date || '';

  const cleanConStart = conStartRaw ? normalizeDateStr(conStartRaw) : '';
  const cleanConEnd = conEndRaw ? normalizeDateStr(conEndRaw) : '';
  const cleanMonthDate = monthDateRaw ? normalizeDateStr(monthDateRaw) : '';

  // 1. Direct date range match / overlap
  if (cleanMonthDate || cleanConStart) {
    const matchedByRange = allInsured.filter((item: any) => {
      const iStart = item.startDate ? normalizeDateStr(item.startDate) : (item.periodId ? `${item.periodId.substring(0, 4)}/01/01` : '');
      const iEnd = item.endDate ? normalizeDateStr(item.endDate) : (item.periodId ? `${item.periodId.substring(0, 4)}/12/29` : '');

      if (iStart && iEnd) {
        if (cleanMonthDate) {
          return cleanMonthDate >= iStart && cleanMonthDate <= iEnd;
        }
        if (cleanConStart && cleanConEnd) {
          return cleanConStart <= iEnd && cleanConEnd >= iStart;
        }
        if (cleanConStart) {
          return cleanConStart >= iStart && cleanConStart <= iEnd;
        }
      } else if (iStart && !iEnd) {
        if (cleanMonthDate) return cleanMonthDate >= iStart;
        if (cleanConEnd) return cleanConEnd >= iStart;
        if (cleanConStart) return cleanConStart >= iStart;
      } else if (!iStart && iEnd) {
        if (cleanMonthDate) return cleanMonthDate <= iEnd;
        if (cleanConStart) return cleanConStart <= iEnd;
      }
      return false;
    });

    if (matchedByRange.length > 0) {
      return { periodId: targetPeriodId, items: matchedByRange };
    }
  }

  // 2. Match by year of contract start date, month date, or contract targetPeriodId
  const year = getJalaliYear(cleanMonthDate || cleanConStart) || (targetPeriodId ? targetPeriodId.split('-')[0] : '');
  if (year) {
    const yearItems = allInsured.filter((item: any) => {
      if (item.startDate && getJalaliYear(item.startDate) === year) return true;
      if (item.endDate && getJalaliYear(item.endDate) === year) return true;
      if (item.periodId && String(item.periodId).startsWith(year)) return true;
      return false;
    });
    if (yearItems.length > 0) {
      return { periodId: yearItems[0].periodId || targetPeriodId, items: yearItems };
    }
  }

  // 3. Resolve contract periodId directly (for legacy items with periodId)
  if (targetPeriodId) {
    const items = allInsured.filter((item: any) => item.periodId === targetPeriodId);
    if (items.length > 0) {
      return { periodId: targetPeriodId, items };
    }
  }

  // 4. Fallback to items defined for fallbackPeriodId
  const fallbackItems = allInsured.filter((item: any) => item.periodId === fallbackPeriodId);
  if (fallbackItems.length > 0) {
    return { periodId: fallbackPeriodId, items: fallbackItems };
  }

  // 5. If still none, use the latest defined insured items available in db
  return { periodId: targetPeriodId || fallbackPeriodId, items: allInsured };
};

