    setIsSubjectToUnemploymentPremium(emp.isSubjectToUnemploymentPremium !== undefined ? emp.isSubjectToUnemploymentPremium : true);
    setIsSubjectToWorkerPremium(emp.isSubjectToWorkerPremium !== undefined ? emp.isSubjectToWorkerPremium : true);
    setGender(emp.gender || 'مرد');
    setMaritalStatus(emp.maritalStatus || (emp.isMarried ? 'متاهل' : 'مجرد'));
    setChildrenList(emp.childrenList || []);
