    setInsuranceDate(emp.insuranceDate || '');
    setInsuranceHistoryDays(emp.insuranceHistoryDays || 0);
    setPersonnelCategoryId(emp.personnelCategoryId || '');
    setMilitaryStatus(emp.militaryStatus || '');
    
    // Load new states
    setHasNationalCardCopy(!!emp.hasNationalCardCopy);
    setHasBirthCertificatePagesCopy(!!emp.hasBirthCertificatePagesCopy);
    setHasPhoto(!!emp.hasPhoto);
    setHasSocialSecurityRegistrationForm(!!emp.hasSocialSecurityRegistrationForm);
    setHasPromissoryNote(!!emp.hasPromissoryNote);
    setHasHealthCard(!!emp.hasHealthCard);
    setHasPreEmploymentExam(!!emp.hasPreEmploymentExam);
    setPromissoryNoteNumber(emp.promissoryNoteNumber || '');
    setPromissoryNoteIssuerName(emp.promissoryNoteIssuerName || '');
    setPromissoryNoteAmount(emp.promissoryNoteAmount !== undefined ? formatWithCommas(emp.promissoryNoteAmount) : '0');
    setHasSupplementaryInsurance(!!emp.hasSupplementaryInsurance);
