    if (selectedEmpCodes.length === 0) return;
    askConfirm(
      'حذف دسته‌جمعی پرسنل منتخب',
      `آیا از حذف دائم و دسته‌جمعی تعداد ${selectedEmpCodes.length} پرسنل انتخابی و کل فیش‌های حقوقی متناظر با آن‌ها اطمینان راسخ دارید؟ این عملیات غیر قابل بازگشت است.`,
      () => {
        const remainingPersonnel = db.personnel.filter(p => !(selectedEmpCodes.includes(p.employeeCode) && p.periodId === activePeriodId));
        const remainingAllocations = db.personnelAllocations.filter(a => !(selectedEmpCodes.includes(a.employeeCode) && a.periodId === activePeriodId));
        const remainingPayrolls = db.payrollItems.filter(p => !(selectedEmpCodes.includes(p.employeeCode) && p.periodId === activePeriodId));

        onUpdateDb({
          ...db,
          personnel: remainingPersonnel,
          personnelAllocations: remainingAllocations,
          payrollItems: remainingPayrolls
        });

        setSelectedEmpCodes([]);
      }
    );
