  const handleToggleSelectAll = () => {
    const displayedCodes = searchedPersonnel.map(p => p.employeeCode);
    const allSelected = displayedCodes.every(c => selectedEmpCodes.includes(c));
    
    if (allSelected) {
      setSelectedEmpCodes(selectedEmpCodes.filter(c => !displayedCodes.includes(c)));
    } else {
      const merged = Array.from(new Set([...selectedEmpCodes, ...displayedCodes]));
      setSelectedEmpCodes(merged);
    }
  };

  const handleToggleSelectOne = (code: string) => {
    if (selectedEmpCodes.includes(code)) {
      setSelectedEmpCodes(selectedEmpCodes.filter(c => c !== code));
    } else {
      setSelectedEmpCodes([...selectedEmpCodes, code]);
    }
  };


